<template><section class="hero"><div class="container"><p class="eyebrow light">Демонстрационный сервис · Санкт-Петербург</p><h1>Столик для хорошего вечера</h1><p>Ищите рестораны по кухне, району и уровню цен. Бронирование доступно после учебного входа.</p></div></section><section class="container filter-panel"><form class="filters" @submit.prevent><label>Кухня<select v-model="filters.cuisine"><option value="">Любая</option><option v-for="value in cuisines" :key="value">{{ value }}</option></select></label><label>Район<select v-model="filters.district"><option value="">Любой</option><option v-for="value in districts" :key="value">{{ value }}</option></select></label><label>Цена<select v-model="filters.price"><option value="">Любая</option><option value="2">₽₽</option><option value="3">₽₽₽</option></select></label><button type="button" class="btn btn-soft" @click="reset">Сбросить</button></form></section><section class="container section"><div class="section-heading"><div><p class="eyebrow">Выбор TableTime</p><h2>Рестораны</h2></div><p class="meta" aria-live="polite">{{ filtered.length }} из {{ restaurants.length }}</p></div><StatusPanel v-if="loading">Загружаем демонстрационные рестораны…</StatusPanel><StatusPanel v-else-if="error" kind="error">{{ error }} <button class="link-button" @click="load">Повторить</button></StatusPanel><div v-else-if="filtered.length" class="restaurant-grid"><RestaurantCard v-for="restaurant in filtered" :key="restaurant.id" :restaurant="restaurant" /></div><div v-else class="empty-state"><h2>Ничего не найдено</h2><p>Сбросьте один из фильтров, чтобы увидеть другие рестораны.</p></div></section></template><script setup>import { computed, onMounted, reactive, ref } from 'vue'; import RestaurantCard from '../components/RestaurantCard.vue'; import StatusPanel from '../components/StatusPanel.vue'; import { restaurantApi } from '../composables/useApi'; const restaurants = ref([]), loading = ref(true), error = ref(''); const filters = reactive({ cuisine:'', district:'', price:'' }); const cuisines = computed(() => [...new Set(restaurants.value.map((r) => r.cuisine))]); const districts = computed(() => [...new Set(restaurants.value.map((r) => r.district))]); const filtered = computed(() => restaurants.value.filter((r) => (!filters.cuisine || r.cuisine === filters.cuisine) && (!filters.district || r.district === filters.district) && (!filters.price || String(r.price) === filters.price))); async function load() { loading.value=true; error.value=''; try { restaurants.value=await restaurantApi.list(); } catch (e) { error.value=e.message; } finally { loading.value=false; } } function reset() { Object.assign(filters,{cuisine:'',district:'',price:''}); } onMounted(load);</script>
